            assertThat(entry.path("policyVersion").asLong()).isEqualTo(1L);
            assertThat(entry.path("signatureKeyIds")).hasSize(2);
            assertThat(entry.path("contentDigest").asText()).hasSize(64);
        }

        // 只读证据查询。
